// --------------------------- REGISTERS

app.post('/registers', async (req, res) => {

  const { registers } = req.body
  const airtableHook = "https://hooks.airtable.com/workflows/v1/genericWebhook/appKBVhi1WrIj5da4/wflRODyYjRYZue6Lp/wtrwS0MlJakhkSOkH"

  // Send to Airtable
  try {
    const response = await axios.post(airtableHook, {registers: registers},
        { headers: {'Content-Type': 'application/json'}}
    );
    res.status(200).send({ msg: "Attendance Registers updated successfully!" });
  } catch (error) {
    res.status(400).send(error);
  }
})

// --------------------------- FILES

app.post('/files', async (req, res) => {
  
    const { airtableFilename, airtableFiletype, airtableUrl, firebaseFolder } = req.body;
    const folder = firebaseFolder || 'airtable';

    try {
        // Fetch file from Airtable
        const response = await axios({
            method: 'GET',
            url: airtableUrl,
            responseType: 'stream'
        });

        const file = admin.storage().bucket().file(`${folder}/${airtableFilename}`);
        const writeStream = file.createWriteStream({
            metadata: {
                contentType: airtableFiletype,
                metadata: {
                    firebaseStorageDownloadTokens: uuidv4()
                }
            }
        });

        // Pipe the Airtable stream into Firebase Storage
        response.data.pipe(writeStream);

        // Wait for upload completion
        await new Promise((resolve, reject) => {
            writeStream.on('finish', resolve);
            writeStream.on('error', reject);
        });

        // Generate Firebase Storage URL
        const fileUrl = `https://firebasestorage.googleapis.com/v0/b/${admin.storage().bucket().name}/o/${encodeURIComponent(folder + '/' + airtableFilename)}?alt=media`;
        
        console.log("File successfully uploaded with URL:\n" + fileUrl);
        res.status(200).send({ firebaseUrl: fileUrl });

    } catch (error) {
        console.error("Error adding file: ", error);
        res.status(500).send({ error: "Error uploading file", details: error.message });
    }
});

// --------------------------- CONTRACTS

app.post('/contract', async (req, res) => {

    const {id} = req.body
    const url = `${process.env.AIRTABLE_API + process.env.AIRTABLE_BASE_MAIN}Enrolments/${id}`
    console.log(`Updating Airtable record ${id} --- ${url}`)

    const response = await fetch(url, {
        method: 'PATCH',
        headers: {
          'Authorization': `Bearer ${process.env.AIRTABLE_API_KEY}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          fields: {
            "Contract": true
          }
        })
      })
    
      if (response.ok) {
        const updatedRecord = await response.json()
        console.log(`Record ${id} updated successfully`, updatedRecord)
        res.status(200).send({ msg: `Contract for Record ${id} confirmed successfully!` })
      } else {
        const error = await response.json();
        console.error(`Error updating record ${id}:`, error);
        res.status(400).send({ error: `Error updating record ${id}: ${error.error}` })
      }
})    

