// --------------------------- WEBINARS

app.post('/webinar-stats', async (req, res) => {

  const { id, accessed, watched, plays } = req.body;
  const playCount = watched === 1 ? plays + 1 : plays

  try {
    const url = `${process.env.AIRTABLE_API}${process.env.AIRTABLE_BASE_ONLINE}Webinar%20Sessions/${id}`;
    const headers = {
      Authorization: `Bearer ${process.env.AIRTABLE_API_KEY}`,
      'Content-Type': 'application/json',
    };

    const response = await axios.patch(url, {
      fields: {
        Accessed: accessed,
        Watched: watched,
        Plays: playCount,
      },
    }, { headers });

    res.status(200).send({ success: 'Stats updated successfully!' });
  } catch (error) {
    console.error('Error updating record:', error.message);
    res.status(400).send({
      error: `Error updating record: ${error.response?.data?.error?.message || error.message}`,
    });
  }
});

app.post('/webinar-register', async (req, res) => {

  const { fname, lname, email, webinar, marketing, source } = req.body;
  let personId = '';

  // Check if email has already been used for this Webinar
  try {
    const url = `${process.env.AIRTABLE_API}${process.env.AIRTABLE_BASE_ONLINE}Webinar%20Sessions?filterByFormula=AND({Email}='${email}',{Webinar ID}='${webinar}')`;
    const headers = {
      Authorization: `Bearer ${process.env.AIRTABLE_API_KEY}`,
      'Content-Type': 'application/json',
    };

    const response = await axios.get(url, { headers });

    if (response.data.records.length > 0) {
      return res.status(400).send({ error: 'It looks like this email address was already used to register for this webinar. If you need help or would like to report an issue please contact us.' });
    }
  } catch (error) {
    console.error('Error checking email:', error.message);
    return res.status(400).send({
      error: `Error checking email: ${error.response?.data?.error?.message || error.message}`,
    });
  }

  // Check if user exists in People table
  try {
    const url = `${process.env.AIRTABLE_API}${process.env.AIRTABLE_BASE_ONLINE}People?filterByFormula=({Email}='${email}')`;
    const headers = {
      Authorization: `Bearer ${process.env.AIRTABLE_API_KEY}`,
      'Content-Type': 'application/json',
    };

    const response = await axios.get(url, { headers });

    if (response.data.records.length > 0) {

      // User exists
      const person = response.data.records[0];
      personId = person.id;

    } else {

      // User does not exist, create new record
      try {
        const url = `${process.env.AIRTABLE_API}${process.env.AIRTABLE_BASE_ONLINE}People`;
        const headers = {
          Authorization: `Bearer ${process.env.AIRTABLE_API_KEY}`,
          'Content-Type': 'application/json',
        };

        const response = await axios.post(url, {
          fields: {
            'First name (Raw)': fname,
            'Surname (Raw)': lname,
            'Email': email,
            'Subscribed': marketing,
          },
        }, { headers });

        personId = response.data.id;
        console.log('Creating new People record:', response.data);
      } catch (error) {
        console.error('Error creating People record:', error.message);
        return res.status(400).send({
          error: `Error creating People record: ${error.response?.data?.error?.message || error.message}`,
        });
      }
    }
  } catch (error) {
    console.error('Error checking People table:', error.message);
    return res.status(400).send({
      error: `Error checking People table: ${error.response?.data?.error?.message || error.message}`,
    });
  }

  // Create Webinar Session
  console.log('Creating Webinar Session record:', { fname, lname, email, webinar, marketing });
  try {
    const url = `${process.env.AIRTABLE_API}${process.env.AIRTABLE_BASE_ONLINE}Webinar%20Sessions`;
    const headers = {
      Authorization: `Bearer ${process.env.AIRTABLE_API_KEY}`,
      'Content-Type': 'application/json',
    };

    const response = await axios.post(url, {
      fields: {
        'Person': [personId],
        'Webinar': [webinar],
        'Send Link': true,
        'Source': source || ""
      },
    }, { headers });

    res.status(200).send({
      success: "Registration successful! You will receive an email shortly with a link to access the webinar. If it doesn't arrive, please check your spam folder.",
      id: response.data.id
     });
  } catch (error) {
    console.error('Error creating Webinar Session record:', error.message);
    res.status(400).send({
      error: `Hmmm. It looks like there was an error when trying to complete your registration.\n\n${error.response?.data?.error?.message || error.message}\n\nPlease refresh your browser window and try again. If the problem persists, please contact us.`,
    });
  }

});


